/* From Uiverse.io by Admin12121 - Tags: card, accept, card design */
.__UIV_SCOPE__ .cookie-warning {
  background: linear-gradient(0deg, #9005bd 0%, #bc28d2 100%);
  box-shadow: 10px 5px 20px 0 rgba(144, 5, 189, 0.3);
  max-width: 400px;
  display: flex;
  color: #FFF;
  flex-direction: column;
  padding: 1.5rem;
  border-radius: 0.6rem;
/*  position: fixed; */
  left: 2.4rem;
  right: 2.4rem;
  bottom: 2.4rem;
  z-index: 100;
}

.__UIV_SCOPE__ .cookie-warning__title {
  font-size: 2rem;
  margin-bottom: 0.8rem;
}

.__UIV_SCOPE__ .cookie-warning__text {
  font-size: 1.1rem;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 1rem;
}

.__UIV_SCOPE__ .cookie-warning a {
  color: rgba(255, 255, 255, 0.8);
}

.__UIV_SCOPE__ .cookie-warning__button-group {
  display: flex;
  justify-content: end;
  flex-wrap: wrap;
  margin-bottom: -0.5rem;
}

.__UIV_SCOPE__ .cookie-warning__button {
  cursor: pointer;
  background-color: rgba(255, 255, 255, 0.2);
  border: none;
  padding: 8px 8px;
  border-radius: 0.6rem;
  margin-right: 0.8rem;
  font-size: 1rem;
  color: #FFF;
  transition: 0.15s ease;
}

.__UIV_SCOPE__ .cookie-warning__button:hover {
  color: #9005bd;
  background-color: rgba(255, 255, 255, 0.8);
}
